internal static byte[] EncodeUtf8WithPreamble(string content)
{
    var preamble = Encoding.UTF8.GetPreamble();
    var body = Encoding.UTF8.GetBytes(content);
    var bytes = new byte[preamble.Length + body.Length];
    Buffer.BlockCopy(preamble, 0, bytes, 0, preamble.Length);
    Buffer.BlockCopy(body, 0, bytes, preamble.Length, body.Length);
    return bytes;
}

internal static async ValueTask ReleaseOwnedLeaseAsync(
    FileSystemManager fs,
    FileSystemManager.CanonicalWriteLease writeLease,
    bool completed,
    Exception? operationFailure)
{
    try { await writeLease.DisposeAsync(); }
    catch (Exception failure) when (operationFailure != null)
    {
        // A secondary release failure cannot turn unresolved publication
        // into an ordinary error eligible for compensation or safe retry.
        operationFailure.Data["CoordinatedLeaseReleaseFailure"] = failure;
    }
    catch (Exception failure) when (completed)
    {
        // Diagnostics are follow-up after an established completed result.
        try { fs.LogCompletedCoordinatedWriteReleaseFailure(failure); }
        catch { /* A failed warning sink cannot change that result. */ }
    }
}

private void ValidateRequiredIsoTimestampField(JsonElement root, string contextPrefix, List<ValidationIssue> issues,
    string propName, string section, string missingCode, string invalidCode, string repairHint)
{
    var fieldPath = $"{contextPrefix}.{propName}";
    if (!root.TryGetProperty(propName, out var value) ||
        value.ValueKind != JsonValueKind.String ||
        string.IsNullOrWhiteSpace(value.GetString()))
    {
        issues.Add(new ValidationIssue(
            fieldPath,
            IssueSeverity.Error,
            $"{propName} обязателен и должен быть ISO 8601 timestamp",
            code: missingCode,
            section: section,
            expected: "ISO 8601 timestamp",
            actual: !root.TryGetProperty(propName, out var actualValue)
                ? "missing"
                : actualValue.ValueKind == JsonValueKind.String
                    ? "missing/empty"
                    : actualValue.ValueKind.ToString(),
            repairHint: repairHint));
        return;
    }

    var timestamp = value.GetString() ?? string.Empty;
    if (!DateTimeOffset.TryParse(timestamp, out _))
    {
        issues.Add(new ValidationIssue(
            fieldPath,
            IssueSeverity.Error,
            $"{propName} должен быть ISO 8601 timestamp",
            code: invalidCode,
            section: section,
            expected: "ISO 8601 timestamp",
            actual: timestamp,
            repairHint: repairHint));
    }
}

